def is_valid(f, max_s):
    # f is a dictionary: f[(x, y)] = value
    # check the condition: f(x1, y1) > f(x2, y2) => f(x1+1, y1) > f(x2+1, y2)
    # and f(x1, y1+1) > f(x2, y2+1)
    # also check f(x1, y1) > f(x2, y2) => f(x1, y1+1) > f(x2, y2+1)
    for (x1, y1), v1 in f.items():
        for (x2, y2), v2 in f.items():
            if v1 > v2:
                # check x+1
                if (x1+1, y1) in f and (x2+1, y2) in f:
                    if f[(x1+1, y1)] <= f[(x2+1, y2)]:
                        return False
                # check y+1
                if (x1, y1+1) in f and (x2, y2+1) in f:
                    if f[(x1, y1+1)] <= f[(x2, y2+1)]:
                        return False
    return True

# Let's test the Cantor pairing functions
def cantor(x, y, type=1):
    s = x + y
    if type == 1:
        return s * (s + 1) // 2 + x
    else:
        return s * (s + 1) // 2 + y

for t in [1, 2]:
    f = {}
    for x in range(5):
        for y in range(5):
            f[(x, y)] = cantor(x, y, t)
    print(f"Type {t} is valid: {is_valid(f, 5)}")

import itertools

def solve(max_s):
    # phi_s is a permutation of {0, ..., s}
    # Condition: for all s < max_s, for all x1, x2 <= s:
    # phi_s(x1) > phi_s(x2) => phi_{s+1}(x1+1) > phi_{s+1}(x2+1)
    # Note that if x1=s, x1+1=s+1, so phi_{s+1}(s+1) must be considered.
    # Also if x2=s, x2+1=s+1.

    # Let's find all such sequences.
    # For s=0, phi_0 = [0]
    # For s=1, phi_1 = [0, 1] or [1, 0]

    phis = [[0]]
    for s in range(1, max_s + 1):
        new_phis = []
        for current_phis in phis:
            prev_phi = current_phis[-1]
            # prev_phi is a permutation of {0, ..., s-1}
            for p in itertools.permutations(range(s + 1)):
                # p is phi_s, which is a permutation of {0, ..., s}
                # Condition: for all x1, x2 <= s-1:
                # prev_phi(x1) > prev_phi(x2) => p(x1+1) > p(x2+1)
                valid = True
                for x1 in range(s):
                    for x2 in range(s):
                        if x1 == x2: continue
                        if prev_phi[x1] > prev_phi[x2]:
                            if p[x1+1] <= p[x2+1]:
                                valid = False
                                break
                        elif prev_phi[x1] < prev_phi[x2]:
                            if p[x1+1] >= p[x2+1]:
                                valid = False
                                break
                    if not valid: break

                if valid:
                    new_phis.append(current_phis + [list(p)])
        phis = new_phis
    return phis

for max_s in range(1, 4):
    results = solve(max_s)
    print(f"max_s={max_s}, number of sequences: {len(results)}")
    for res in results:
        print(res)

def solve_N_final_v2():
    total_min = 0
    total_max = 0
    for s in range(200):
        m_s = min(s, 99) - max(0, s-99) + 1
        if m_s <= 0: continue
        v_s = s * (s + 1) // 2
        o_set = 0
        e_set = 0
        for i in range(s + 1):
            if (v_s + i) % 2 != 0:
                o_set += 1
            else:
                e_set += 1
        if s <= 99:
            k_s = o_set
            total_min += k_s
            total_max += k_s
        else:
            total_min += max(0, m_s - e_set)
            total_max += min(m_s, o_set)
    return total_min, total_max

print(solve_N_final_v2())

